// Writes the version constants the code needs from each package.json, so a release only ever
// changes package.json. Runs before every build (npm run build); the generated files are committed
// so a fresh checkout type-checks, and test/versions.test.ts fails if they drift.
import { readFileSync, writeFileSync } from 'node:fs';

const root = new URL('../', import.meta.url);
const version = (pkg) => JSON.parse(readFileSync(new URL(`packages/${pkg}/package.json`, root), 'utf8')).version;
const header = '// Generated by scripts/sync-versions.mjs from package.json. Do not edit; change package.json.\n';

const mcp = version('mcp');
const extension = version('extension');
// Chrome Web Store: one to four dot-separated integers, each 0-65535, no pre-release tags.
if (!/^\d{1,5}(\.\d{1,5}){0,3}$/.test(extension)) throw new Error(`extension version ${extension} is not a valid Chrome extension version (1-4 integers, e.g. 1.2.0)`);

const write = (path, text) => {
  const url = new URL(path, root);
  let old = '';
  try {
    old = readFileSync(url, 'utf8');
  } catch {}
  if (old !== text) writeFileSync(url, text);
};
write('packages/mcp/src/version.ts', `${header}export const VERSION = '${mcp}';\n`);
write('packages/extension/src/versions.ts', `${header}export const EXTENSION_VERSION = '${extension}';\n/** The repospector-mcp release whose native host matches this extension (local mode). */\nexport const MCP_VERSION = '${mcp}';\n`);
// The Claude Code plugin starts the published server at this exact version.
const mcpJson = new URL('packages/mcp/plugin/.mcp.json', root);
const cfg = JSON.parse(readFileSync(mcpJson, 'utf8'));
cfg.mcpServers.repospector.args = ['-y', `repospector-mcp@${mcp}`];
write('packages/mcp/plugin/.mcp.json', `${JSON.stringify(cfg, null, 2)}\n`);
const pluginJson = new URL('packages/mcp/plugin/.claude-plugin/plugin.json', root);
const plugin = JSON.parse(readFileSync(pluginJson, 'utf8'));
if ('version' in plugin) write('packages/mcp/plugin/.claude-plugin/plugin.json', `${JSON.stringify({ ...plugin, version: mcp }, null, 2)}\n`);
// Docs that show the install command.
for (const doc of ['packages/extension/static/help.html', 'README.md']) {
  const url = new URL(doc, root);
  write(doc, readFileSync(url, 'utf8').replace(/repospector-mcp@\d+\.\d+\.\d+(-[0-9A-Za-z.-]+)?/g, `repospector-mcp@${mcp}`));
}
console.log(`versions: extension ${extension}, repospector-mcp ${mcp}`);
